"""Transcribe the host's literal Python-shaped values to Rust, never decoding wire bytes.
Run from any directory, then cargo fmt. Generated cases retain each exact host line;
the Rust test checks that the host file and all 66 literal cases stay paired.
"""
import ast
import json
import re
from pathlib import Path

root = Path(__file__).parent
# Literal field types, independent of the codec's field ordering and tags.
fields = {
    'id': 'RecordId', 'left_id': 'RecordId', 'right_id': 'RecordId',
    'field': 'FieldRef', 'tag': 'FieldRef', 'value': 'ScanValue',
    'token': 'String', 'protocol_version': 'u32', 'flags': 'u32',
    'fields': 'Fields', 'select': 'Selection', 'filter': '[Predicate]',
    'group_by': '[FieldRef]', 'aggregates': '[AggregateSpec]', 'limit': '?usize',
    'updates': '[TransactionOp]', 'table': 'String', 'relation': 'String',
    'records': '[RecordId]', 'values': '[ScanValue]', 'code': 'ErrorCode',
    'message': 'String', 'index': 'usize', 'groups': '[AggregateGroup]',
    'kinds': '[String]', 'relations': '[RelationDescriptor]', 'names': '[String]',
    'primary': 'String', 'count': 'u64', 'results': '[WriteResult]',
    'op': 'CompareOp', 'func': 'AggregateFn', 'key': 'Fields', 'name': 'String',
    'kind': 'JoinRelation', 'target_table': '?String', 'right_table': '?String',
    'left_filter': '[Predicate]', 'right_filter': '[Predicate]',
    'value_kind': 'ValueKind', 'capabilities': 'FieldCapabilities',
    'filter_eq': 'bool', 'scan': 'bool', 'update': 'bool',
    'parent_children': 'bool', 'neighbors': 'bool', 'ops': '[WriteOp]', 'atomic': 'bool',
    'guard': 'Predicate', 'order_by': 'FieldRef', 'after': '?(ScanValue,RecordId)',
    'slots_reclaimed': 'u64', 'log_entries_folded': 'u64', 'edge_logs_folded': 'u64',
}

def field_type(owner, field):
    overrides = {
        ('Request::Link', 'left'): 'RecordId', ('Request::Link', 'right'): 'RecordId',
        ('JoinSpec', 'relation'): 'JoinRelation', ('JoinSpec', 'left'): 'Selection',
        ('JoinSpec', 'right'): 'Selection', ('JoinedRow', 'left'): 'Fields',
        ('JoinedRow', 'right'): 'Fields', ('Response::Rows', 'rows'): '[(RecordId,Fields)]',
        ('Response::JoinedRows', 'rows'): '[JoinedRow]', ('Response::Compacted', 'records'): 'u64',
        ('DomainSchema', 'fields'): '[FieldDescriptor]', ('DomainSchema', 'relations'): 'RelationCapabilities',
        ('AggregateSpec', 'field'): '?FieldRef', ('Request::Page', 'limit'): 'u64',
    }
    return overrides.get((owner, field), fields.get(field))

def emit(ty, value):
    assert ty is not None, value
    if ty.startswith('?'):
        return 'None' if value is None else 'Some(' + emit(ty[1:], value) + ')'
    if ty.startswith('['):
        return 'vec![' + ', '.join(emit(ty[1:-1], v) for v in value) + ']'
    if ty.startswith('('):
        return '(' + ', '.join(emit(t, v) for t, v in zip(ty[1:-1].split(','), value, strict=True)) + ')'
    if ty == 'Fields':
        return emit('[(FieldRef,ScanValue)]', value)
    if ty == 'RecordId':
        return f'RecordId::from_u128(0x{value})'
    if ty == 'String':
        return json.dumps(value) + '.into()'
    if ty == 'bool':
        return str(value).lower()
    if ty in ('FieldRef', 'usize', 'u32', 'u64', 'i64', 'f64'):
        return str(value)
    if isinstance(value, dict):
        return ty + ' { ' + ', '.join(k + ': ' + emit(field_type(ty,k), v) for k,v in value.items()) + ' }'
    if isinstance(value, str):
        return ty + '::' + value
    variant = value[0]
    name = ty + '::' + variant
    if ty in ('Request', 'Response', 'WriteOp'):
        if variant == 'Join':
            return name + '(' + emit('JoinSpec', value[1]) + ')'
        if variant == 'Schema':
            return name + '(' + emit('DomainSchema', value[1]) + ')'
        if not value[1]:
            return name
        return name + ' { ' + ', '.join(k + ': ' + emit(field_type(name,k), v) for k,v in value[1].items()) + ' }'
    if len(value) == 1:
        return name
    inner = {'ScanValue': {'U32':'u32','I64':'i64','Bool':'bool','Str':'String','F64':'f64','StrList':'[String]'},
             'Selection': {'Fields':'[FieldRef]'}, 'JoinRelation': {'Neighbors':'?String'},
             'WriteResult': {'Failed':'ErrorCode'}}[ty][variant]
    return name + '(' + emit(inner, value[1]) + ')'

cases = []
for line in (root / 'step4b-fixture-expected-values.txt').read_text(encoding='utf-8').splitlines()[2:]:
    if not line:
        continue
    match = re.fullmatch(r'(.+) (\d+) (\(.*)', line)
    name, version, literal = match.groups()
    ty = name.split('/')[0]
    cases.append('(' + json.dumps(line) + ', Expected::' + ty + '(' + emit(ty, ast.literal_eval(literal)) + '))')
assert len(cases) == 66
(root / 'expected_cases.rs').write_text('// Generated by generate_expected.py from host literals only.\nuse uc_protocol::*;\npub enum Expected { Request(Request), Response(Response) }\npub fn cases() -> Vec<(&\'static str, Expected)> { vec![\n' + ',\n'.join(cases) + '\n] }\n', encoding='utf-8', newline='\n')
